SET LOCAL lock_timeout='5s';
DO $$ BEGIN IF current_user<>'postgres' OR session_user<>'postgres' THEN RAISE EXCEPTION 'postgres required'; END IF; END $$;
REVOKE INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER ON public.listings FROM PUBLIC,anon,authenticated,service_role;
DO $$ DECLARE a record; BEGIN FOR a IN SELECT attname FROM pg_attribute WHERE attrelid='public.listings'::regclass AND attnum>0 AND NOT attisdropped LOOP
 EXECUTE format('REVOKE INSERT (%I), UPDATE (%I), REFERENCES (%I) ON public.listings FROM PUBLIC,anon,authenticated,service_role',a.attname,a.attname,a.attname); END LOOP; END $$;
